1	package com.example.starter.cutover.service;
2	
3	import com.example.starter.cutover.BusinessRuleException;
4	import com.example.starter.cutover.ConflictException;
5	import com.example.starter.cutover.EventType;
6	import com.example.starter.cutover.NotFoundException;
7	import com.example.starter.cutover.Priority;
8	import com.example.starter.cutover.RequestStatus;
9	import com.example.starter.cutover.StepStatus;
10	import com.example.starter.cutover.StepType;
11	import com.example.starter.cutover.dto.ActionResult;
12	import com.example.starter.cutover.dto.ApproveRequest;
13	import com.example.starter.cutover.dto.CreateCutoverRequest;
14	import com.example.starter.cutover.dto.EventView;
15	import com.example.starter.cutover.dto.ExpireCheckRequest;
16	import com.example.starter.cutover.dto.RequestView;
17	import com.example.starter.cutover.dto.SealRequest;
18	import com.example.starter.cutover.dto.StartExecutionRequest;
19	import com.example.starter.cutover.dto.StepDefinition;
20	import com.example.starter.cutover.dto.StepReportRequest;
21	import com.example.starter.cutover.dto.StepView;
22	import com.example.starter.cutover.model.CutoverEventPO;
23	import com.example.starter.cutover.model.CutoverRequestPO;
24	import com.example.starter.cutover.model.CutoverStepPO;
25	import com.example.starter.cutover.repo.CutoverRepository;
26	import com.example.starter.cutover.support.FingerprintUtil;
27	import com.fasterxml.jackson.core.type.TypeReference;
28	import com.fasterxml.jackson.databind.ObjectMapper;
29	import java.time.Duration;
30	import java.time.LocalDateTime;
31	import java.util.ArrayList;
32	import java.util.Arrays;
33	import java.util.List;
34	import java.util.Set;
35	import org.springframework.beans.factory.annotation.Value;
36	import org.springframework.dao.DuplicateKeyException;
37	import org.springframework.stereotype.Service;
38	import org.springframework.transaction.annotation.Transactional;
39	
40	/**
41	 * 割接领域服务。
42	 *
43	 * <p>关键口径：</p>
44	 * <ul>
45	 *   <li>窗口冲突按半开区间 [start,end)，端点相接不冲突；同一设备同一时间只允许一个已批准割接；</li>
46	 *   <li>同窗口高优先级变更存在时，低优先级申请拒绝；高优先级新申请抢占低优先级在途申请；</li>
47	 *   <li>窗口最长 4 小时，恰 4 小时合法；</li>
48	 *   <li>关键验证点自该步开始起 10 分钟（恰满 10 分钟）未通过、或任一硬性检查失败，同一事务内
49	 *       下达回退指令并冻结后续步骤；</li>
50	 *   <li>窗口结束（atTime&gt;=end）仍有未完成步骤 -> WINDOW_EXPIRED 并强制回退；
51	 *       恰在窗口终点（reportedAt==end）完成的步骤有效；</li>
52	 *   <li>requestId/requestUid 幂等：指纹覆盖全部业务字段，同键同参返回首次结果，
53	 *       同键异参 409 且不产生新记录；</li>
54	 *   <li>回退与验证/封板依靠请求行 FOR UPDATE 串行化，终态唯一。</li>
55	 * </ul>
56	 */
57	@Service
58	public class CutoverService {
59	
60	    private static final ObjectMapper JSON = new ObjectMapper();
61	    private static final Set<String> ACTIVE_STATUS =
62	            Set.of(RequestStatus.APPROVED.name(), RequestStatus.EXECUTING.name());
63	
64	    private final CutoverRepository repo;
65	
66	    /** 窗口最大分钟数，默认 240（4 小时，恰达合法）。 */
67	    @Value("${cutover.max-window-minutes:240}")
68	    private long maxWindowMinutes;
69	
70	    /** 关键验证点超时分钟数，默认 10（恰满判定超时）。 */
71	    @Value("${cutover.verification-timeout-minutes:10}")
72	    private long verificationTimeoutMinutes;
73	
74	    public CutoverService(CutoverRepository repo) {
75	        this.repo = repo;
76	    }
77	
78	    // ---------------- 申请 ----------------
79	
80	    @Transactional
81	    public ActionResult create(CreateCutoverRequest req) {
82	        if (!repo.deviceExists(req.deviceCode())) {
83	            throw new BusinessRuleException("设备不存在: " + req.deviceCode());
84	        }
85	        if (!req.windowEnd().isAfter(req.windowStart())) {
86	            throw new BusinessRuleException("窗口结束时间必须晚于开始时间");
87	        }
88	        long minutes = Duration.between(req.windowStart(), req.windowEnd()).toMinutes();
89	        if (minutes > maxWindowMinutes) {
90	            throw new BusinessRuleException(
91	                    "割接窗口最长 " + maxWindowMinutes + " 分钟，当前 " + minutes + " 分钟");
92	        }
93	
94	        String fp = fingerprintRequest(req);
95	        CutoverRequestPO existing = repo.findRequest(req.requestId());
96	        if (existing != null) {
97	            if (!existing.getFingerprint().equals(fp)) {
98	                throw new ConflictException("requestId=" + req.requestId()
99	                        + " 已存在但业务参数不一致（同键异参）");
100	            }
101	            return new ActionResult(true, "同键同参重放，返回首次结果", toView(existing));
102	        }
103	
104	        // 锁住设备行，串行化同设备并发申请，保证重叠/优先级判定不出现幻读。
105	        repo.lockDevice(req.deviceCode());
106	        // 拿锁后复查：并发同 requestId 的首个事务可能已提交。
107	        CutoverRequestPO afterLock = repo.findRequest(req.requestId());
108	        if (afterLock != null) {
109	            if (!afterLock.getFingerprint().equals(fp)) {
110	                throw new ConflictException("requestId=" + req.requestId()
111	                        + " 已存在但业务参数不一致（同键异参）");
112	            }
113	            return new ActionResult(true, "同键同参重放，返回首次结果", toView(afterLock));
114	        }
115	
116	        List<CutoverRequestPO> overlaps = repo.findOverlappingActive(
117	                req.deviceCode(), req.windowStart(), req.windowEnd(), req.requestId());
118	        Priority newPriority = req.priority();
119	        for (CutoverRequestPO overlap : overlaps) {
120	            Priority that = Priority.valueOf(overlap.getPriority());
121	            // 已进入执行的割接实际占用设备，任何新申请（含更高优先级）都拒绝；
122	            // 已批准待执行的同级/高级割接同样阻断本申请。
123	            if (RequestStatus.EXECUTING.name().equals(overlap.getStatus())
124	                    || that.ordinal() <= newPriority.ordinal()) {
125	                CutoverRequestPO rejected = buildNewRequest(req, fp, RequestStatus.REJECTED,
126	                        "窗口[" + req.windowStart() + "," + req.windowEnd()
127	                                + ")与已在途割接 " + overlap.getRequestId()
128	                                + "（优先级 " + that + "，状态 " + overlap.getStatus()
129	                                + "）冲突，优先级未占优，申请拒绝");
130	                repo.insertRequest(rejected);
131	                return new ActionResult(false,
132	                        "因同窗口更高/同级优先级割接在途，申请被拒绝", toView(rejected));
133	            }
134	        }
135	        // 本申请优先级严格更高：抢占拒绝所有重叠且尚待执行（APPROVED）的低优先级申请。
136	        for (CutoverRequestPO overlap : overlaps) {
137	            overlap.setStatus(RequestStatus.REJECTED.name());
138	            overlap.setRejectReason("被更高优先级新申请 " + req.requestId()
139	                    + "（优先级 " + newPriority + "）抢占拒绝");
140	            overlap.setUpdatedAt(LocalDateTime.now());
141	            repo.updateMutable(overlap);
142	        }
143	
144	        LocalDateTime now = LocalDateTime.now();
145	        CutoverRequestPO po = buildNewRequest(req, fp, RequestStatus.SUBMITTED, null);
146	        po.setCreatedAt(now);
147	        po.setUpdatedAt(now);
148	        repo.insertRequest(po);
149	
150	        int seq = 1;
151	        for (StepDefinition sd : req.steps()) {
152	            if (sd.type() == StepType.ROLLBACK) {
153	                throw new BusinessRuleException("回退步骤由系统生成，申请中不允许指定 ROLLBACK 类型");
154	            }
155	            CutoverStepPO step = new CutoverStepPO();
156	            step.setRequestId(req.requestId());
157	            step.setSeqNo(seq++);
158	            step.setStepName(sd.name());
159	            step.setStepType(sd.type().name());
160	            step.setStatus(StepStatus.PENDING.name());
161	            step.setCreatedAt(now);
162	            step.setUpdatedAt(now);
163	            repo.insertStep(step);
164	        }
165	        return new ActionResult(false, "割接申请已受理，状态 SUBMITTED", toView(po));
166	    }
167	
168	    // ---------------- 影响分析 ----------------
169	
170	    @Transactional
171	    public ActionResult analyze(String requestId) {
172	        CutoverRequestPO po = mustLock(requestId);
173	        if (po.getImpactSystems() != null) {
174	            return new ActionResult(true, "影响分析已完成，结果可复算", toView(po));
175	        }
176	        if (!RequestStatus.SUBMITTED.name().equals(po.getStatus())) {
177	            throw new BusinessRuleException("当前状态 " + po.getStatus() + " 不允许执行影响分析");
178	        }
179	        List<String> systems = repo.findSystemsByDevice(po.getDeviceCode());
180	        po.setImpactSystems(String.join(",", systems));
181	        po.setStatus(RequestStatus.IMPACT_ANALYZED.name());
182	        po.setUpdatedAt(LocalDateTime.now());
183	        repo.updateMutable(po);
184	        return new ActionResult(false,
185	                "影响分析完成，命中 " + systems.size() + " 个关联业务系统", toView(po));
186	    }
187	
188	    // ---------------- 审批 ----------------
189	
190	    @Transactional
191	    public ActionResult approve(ApproveRequest req) {
192	        String fp = FingerprintUtil.sha256("APPROVE", req.requestId(),
193	                req.approved(), req.remark());
194	        CutoverEventPO existed = repo.findEvent(req.requestUid());
195	        if (existed != null) {
196	            return resolveIdempotent(existed, fp, req.requestId());
197	        }
198	
199	        CutoverRequestPO po = mustLock(req.requestId());
200	        CutoverEventPO afterLock = repo.findEvent(req.requestUid());
201	        if (afterLock != null) {
202	            return resolveIdempotent(afterLock, fp, req.requestId());
203	        }
204	        String message;
205	        if (Boolean.TRUE.equals(req.approved())) {
206	            if (ACTIVE_STATUS.contains(po.getStatus())) {
207	                return new ActionResult(true, "该割接已处于批准/执行状态，幂等返回", toView(po));
208	            }
209	            if (RequestStatus.REJECTED.name().equals(po.getStatus())) {
210	                throw new BusinessRuleException("申请已被拒绝，不能审批通过");
211	            }
212	            if (!RequestStatus.IMPACT_ANALYZED.name().equals(po.getStatus())) {
213	                throw new BusinessRuleException("尚未完成影响分析，不能审批；当前状态 "
214	                        + po.getStatus());
215	            }
216	            // 审批前再次串行化并复核同设备窗口冲突。
217	            repo.lockDevice(po.getDeviceCode());
218	            List<CutoverRequestPO> overlaps = repo.findOverlappingActive(
219	                    po.getDeviceCode(), po.getWindowStart(), po.getWindowEnd(),
220	                    po.getRequestId());
221	            if (!overlaps.isEmpty()) {
222	                throw new BusinessRuleException("审批失败：同设备窗口存在在途割接 "
223	                        + overlaps.get(0).getRequestId());
224	            }
225	            po.setStatus(RequestStatus.APPROVED.name());
226	            message = "审批通过，状态 APPROVED";
227	        } else {
228	            if (RequestStatus.REJECTED.name().equals(po.getStatus())) {
229	                return new ActionResult(true, "该割接已是拒绝终态，幂等返回", toView(po));
230	            }
231	            if (ACTIVE_STATUS.contains(po.getStatus())
232	                    || RequestStatus.VERIFIED.name().equals(po.getStatus())
233	                    || RequestStatus.SEALED.name().equals(po.getStatus())) {
234	                throw new BusinessRuleException("割接已进入执行/终态，不能拒绝");
235	            }
236	            po.setStatus(RequestStatus.REJECTED.name());
237	            po.setRejectReason(req.remark() == null || req.remark().isBlank()
238	                    ? "审批拒绝" : req.remark());
239	            message = "审批拒绝，状态 REJECTED";
240	        }
241	        po.setUpdatedAt(LocalDateTime.now());
242	        repo.updateMutable(po);
243	        insertEvent(req.requestUid(), req.requestId(), EventType.APPROVE, null, fp,
244	                message, false);
245	        return new ActionResult(false, message, toView(po));
246	    }
247	
248	    // ---------------- 开始窗口执行 ----------------
249	
250	    @Transactional
251	    public ActionResult startExecution(StartExecutionRequest req) {
252	        String fp = FingerprintUtil.sha256("EXECUTE", req.requestId(), req.startTime());
253	        CutoverEventPO existed = repo.findEvent(req.requestUid());
254	        if (existed != null) {
255	            return resolveIdempotent(existed, fp, req.requestId());
256	        }
257	
258	        CutoverRequestPO po = mustLock(req.requestId());
259	        CutoverEventPO afterLock = repo.findEvent(req.requestUid());
260	        if (afterLock != null) {
261	            return resolveIdempotent(afterLock, fp, req.requestId());
262	        }
263	        if (RequestStatus.EXECUTING.name().equals(po.getStatus())) {
264	            return new ActionResult(true, "割接已在执行中，幂等返回", toView(po));
265	        }
266	        if (!RequestStatus.APPROVED.name().equals(po.getStatus())) {
267	            throw new BusinessRuleException("只有 APPROVED 状态可开始执行，当前状态 "
268	                    + po.getStatus());
269	        }
270	        if (req.startTime().isBefore(po.getWindowStart())
271	                || req.startTime().isAfter(po.getWindowEnd())) {
272	            throw new BusinessRuleException("执行开始时间必须落在窗口 [start,end] 内");
273	        }
274	        po.setStatus(RequestStatus.EXECUTING.name());
275	        po.setExecStartedAt(req.startTime());
276	        po.setUpdatedAt(LocalDateTime.now());
277	        repo.updateMutable(po);
278	        String message = "进入窗口执行，执行开始时间 " + req.startTime();
279	        insertEvent(req.requestUid(), req.requestId(), EventType.EXECUTE_START, null, fp,
280	                message, false);
281	        return new ActionResult(false, message, toView(po));
282	    }
283	
284	    // ---------------- 步骤逐条回报 ----------------
285	
286	    @Transactional
287	    public ActionResult report(StepReportRequest req) {
288	        String fp = FingerprintUtil.sha256("REPORT", req.requestId(), req.seqNo(),
289	                req.success(), req.reportedAt(), req.remark());
290	        CutoverEventPO existed = repo.findEvent(req.requestUid());
291	        if (existed != null) {
292	            return resolveIdempotent(existed, fp, req.requestId());
293	        }
294	
295	        // 同一事务内锁定申请行与全部步骤行，回退/验证/封板竞态在此串行化。
296	        CutoverRequestPO po = mustLock(req.requestId());
297	        List<CutoverStepPO> steps = repo.lockSteps(req.requestId());
298	        CutoverEventPO afterLock = repo.findEvent(req.requestUid());
299	        if (afterLock != null) {
300	            return resolveIdempotent(afterLock, fp, req.requestId());
301	        }
302	
303	        // 封板后补报：只记迟到事件，不改任何步骤/申请状态。
304	        if (RequestStatus.SEALED.name().equals(po.getStatus())) {
305	            insertEvent(req.requestUid(), req.requestId(), EventType.LATE_REPORT,
306	                    req.seqNo(), fp, "封板后补报步骤，记为迟到事件", true);
307	            return new ActionResult(false, "割接已封板，补报仅记录为迟到事件", toView(po));
308	        }
309	        // 已回退终态：步骤已冻结，拒绝任何新回报。
310	        if (RequestStatus.ROLLED_BACK.name().equals(po.getStatus())
311	                || RequestStatus.WINDOW_EXPIRED.name().equals(po.getStatus())) {
312	            throw new BusinessRuleException("割接已因 " + po.getRollbackCause()
313	                    + " 回退终态，步骤已冻结，不能继续回报");
314	        }
315	        if (!RequestStatus.EXECUTING.name().equals(po.getStatus())) {
316	            throw new BusinessRuleException("只有 EXECUTING 状态可回报步骤，当前状态 "
317	                    + po.getStatus());
318	        }
319	
320	        CutoverStepPO target = steps.stream()
321	                .filter(s -> s.getSeqNo().equals(req.seqNo()))
322	                .findFirst()
323	                .orElseThrow(() -> new BusinessRuleException(
324	                        "步骤不存在: seqNo=" + req.seqNo()));
325	        if (StepStatus.FROZEN.name().equals(target.getStatus())) {
326	            throw new BusinessRuleException("步骤已被回退指令冻结，不能回报");
327	        }
328	        if (StepStatus.SUCCESS.name().equals(target.getStatus())) {
329	            throw new BusinessRuleException("步骤 seqNo=" + req.seqNo() + " 已成功回报");
330	        }
331	        CutoverStepPO expected = steps.stream()
332	                .filter(s -> StepStatus.PENDING.name().equals(s.getStatus())
333	                        || StepStatus.RUNNING.name().equals(s.getStatus()))
334	                .findFirst()
335	                .orElseThrow(() -> new BusinessRuleException("没有可回报的在途步骤"));
336	        if (!expected.getSeqNo().equals(target.getSeqNo())) {
337	            throw new BusinessRuleException("步骤必须按序回报，下一个待回报步骤 seqNo="
338	                    + expected.getSeqNo());
339	        }
340	        if (req.reportedAt().isBefore(po.getWindowStart())) {
341	            throw new BusinessRuleException("回报时间早于窗口开始时间");
342	        }
343	
344	        LocalDateTime startedAt = target.getSeqNo() == 1
345	                ? po.getExecStartedAt()
346	                : steps.stream()
347	                    .filter(s -> s.getSeqNo() == target.getSeqNo() - 1)
348	                    .map(CutoverStepPO::getReportedAt).findFirst().orElse(null);
349	        LocalDateTime now = LocalDateTime.now();
350	        target.setStartedAt(startedAt);
351	
352	        // 窗口口径：reportedAt > windowEnd 才属超期；恰在窗口终点完成有效。
353	        boolean pastWindow = req.reportedAt().isAfter(po.getWindowEnd());
354	
355	        if (pastWindow) {
356	            target.setStatus(StepStatus.FAILED.name());
357	            target.setReportedAt(req.reportedAt());
358	            target.setUpdatedAt(now);
359	            persistStep(target);
360	            String message = "回报时间 " + req.reportedAt() + " 已晚于窗口终点 "
361	                    + po.getWindowEnd() + "，强制回退";
362	            triggerRollback(po, steps, "WINDOW_EXPIRED", req.seqNo(), req.reportedAt());
363	            insertEvent(req.requestUid(), req.requestId(), EventType.STEP_REPORT,
364	                    req.seqNo(), fp, message, false);
365	            return new ActionResult(false, message, toView(repo.lockRequest(req.requestId())));
366	        }
367	
368	        if (Boolean.FALSE.equals(req.success())) {
369	            String cause = switch (StepType.valueOf(target.getStepType())) {
370	                case HARDCHECK -> "HARDCHECK_FAILED";
371	                case CRITICAL -> "CRITICAL_FAILED";
372	                default -> "STEP_FAILED";
373	            };
374	            target.setStatus(StepStatus.FAILED.name());
375	            target.setReportedAt(req.reportedAt());
376	            target.setUpdatedAt(now);
377	            persistStep(target);
378	            String message = "步骤 seqNo=" + req.seqNo() + " 类型 " + target.getStepType()
379	                    + " 失败，命中回退判据 " + cause;
380	            triggerRollback(po, steps, cause, req.seqNo(), req.reportedAt());
381	            insertEvent(req.requestUid(), req.requestId(), EventType.STEP_REPORT,
382	                    req.seqNo(), fp, message, false);
383	            return new ActionResult(false, message, toView(repo.lockRequest(req.requestId())));
384	        }
385	
386	        // success=true：关键验证点还要判定 10 分钟超时（恰满 10 分钟即超时）。
387	        if (StepType.CRITICAL.name().equals(target.getStepType()) && startedAt != null) {
388	            long elapsed = Duration.between(startedAt, req.reportedAt()).toMinutes();
389	            if (elapsed >= verificationTimeoutMinutes) {
390	                target.setStatus(StepStatus.FAILED.name());
391	                target.setReportedAt(req.reportedAt());
392	                target.setUpdatedAt(now);
393	                persistStep(target);
394	                String message = "关键验证点 seqNo=" + req.seqNo() + " 用时 " + elapsed
395	                        + " 分钟，恰满/超过 " + verificationTimeoutMinutes
396	                        + " 分钟超时阈值，自动回退";
397	                triggerRollback(po, steps, "CRITICAL_TIMEOUT", req.seqNo(), req.reportedAt());
398	                insertEvent(req.requestUid(), req.requestId(), EventType.STEP_REPORT,
399	                        req.seqNo(), fp, message, false);
400	                return new ActionResult(false, message,
401	                        toView(repo.lockRequest(req.requestId())));
402	            }
403	        }
404	
405	        target.setStatus(StepStatus.SUCCESS.name());
406	        target.setReportedAt(req.reportedAt());
407	        target.setUpdatedAt(now);
408	        persistStep(target);
409	
410	        boolean allSuccess = repo.lockSteps(req.requestId()).stream()
411	                .allMatch(s -> StepStatus.SUCCESS.name().equals(s.getStatus()));
412	        String message;
413	        if (allSuccess) {
414	            po.setStatus(RequestStatus.VERIFIED.name());
415	            po.setUpdatedAt(now);
416	            repo.updateMutable(po);
417	            message = "步骤 seqNo=" + req.seqNo() + " 成功，全部步骤完成，验证通过 VERIFIED";
418	        } else {
419	            message = "步骤 seqNo=" + req.seqNo() + " 成功，等待后续步骤回报";
420	        }
421	        insertEvent(req.requestUid(), req.requestId(), EventType.STEP_REPORT,
422	                req.seqNo(), fp, message, false);
423	        return new ActionResult(false, message, toView(repo.lockRequest(req.requestId())));
424	    }
425	
426	    // ---------------- 窗口超期巡检 ----------------
427	
428	    @Transactional
429	    public ActionResult expireCheck(ExpireCheckRequest req) {
430	        String fp = FingerprintUtil.sha256("EXPIRE", req.requestId(), req.atTime());
431	        CutoverEventPO existed = repo.findEvent(req.requestUid());
432	        if (existed != null) {
433	            return resolveIdempotent(existed, fp, req.requestId());
434	        }
435	
436	        CutoverRequestPO po = mustLock(req.requestId());
437	        List<CutoverStepPO> steps = repo.lockSteps(req.requestId());
438	        CutoverEventPO afterLock = repo.findEvent(req.requestUid());
439	        if (afterLock != null) {
440	            return resolveIdempotent(afterLock, fp, req.requestId());
441	        }
442	
443	        String status = po.getStatus();
444	        if (RequestStatus.SEALED.name().equals(status)
445	                || RequestStatus.ROLLED_BACK.name().equals(status)
446	                || RequestStatus.WINDOW_EXPIRED.name().equals(status)
447	                || RequestStatus.REJECTED.name().equals(status)) {
448	            String message = "割接已处于终态 " + status + "，巡检幂等返回";
449	            insertEvent(req.requestUid(), req.requestId(), EventType.EXPIRE_CHECK, null, fp,
450	                    message, false);
451	            return new ActionResult(false, message, toView(po));
452	        }
453	        if (RequestStatus.VERIFIED.name().equals(status)) {
454	            String message = "割接已验证通过，窗口正常收口，无需强制回退";
455	            insertEvent(req.requestUid(), req.requestId(), EventType.EXPIRE_CHECK, null, fp,
456	                    message, false);
457	            return new ActionResult(false, message, toView(po));
458	        }
459	
460	        // 关键验证点超时巡检：当前在途步骤为 CRITICAL 且自其开始（首步=执行开始，
461	        // 其余=上一步完成时间）恰满/超过 10 分钟仍未通过 -> CRITICAL_TIMEOUT 自动回退。
462	        CutoverStepPO current = steps.stream()
463	                .filter(s -> StepStatus.PENDING.name().equals(s.getStatus())
464	                        || StepStatus.RUNNING.name().equals(s.getStatus()))
465	                .findFirst().orElse(null);
466	        if (current != null && StepType.CRITICAL.name().equals(current.getStepType())) {
467	            LocalDateTime criticalStart = current.getSeqNo() == 1
468	                    ? po.getExecStartedAt()
469	                    : steps.stream()
470	                        .filter(s -> s.getSeqNo() == current.getSeqNo() - 1)
471	                        .map(CutoverStepPO::getReportedAt).findFirst().orElse(null);
472	            if (criticalStart != null
473	                    && !req.atTime().isBefore(criticalStart.plusMinutes(verificationTimeoutMinutes))) {
474	                String m = "巡检时间 " + req.atTime() + " 关键验证点 seqNo=" + current.getSeqNo()
475	                        + " 自 " + criticalStart + " 起恰满/超过 " + verificationTimeoutMinutes
476	                        + " 分钟未通过，自动回退";
477	                triggerRollback(po, steps, "CRITICAL_TIMEOUT", current.getSeqNo(), req.atTime());
478	                insertEvent(req.requestUid(), req.requestId(), EventType.EXPIRE_CHECK, null, fp,
479	                        m, false);
480	                return new ActionResult(false, m, toView(repo.lockRequest(req.requestId())));
481	            }
482	        }
483	
484	        if (req.atTime().isBefore(po.getWindowEnd())) {
485	            String message = "窗口尚未结束（巡检时间 " + req.atTime() + " < 窗口终点 "
486	                    + po.getWindowEnd() + "）";
487	            insertEvent(req.requestUid(), req.requestId(), EventType.EXPIRE_CHECK, null, fp,
488	                    message, false);
489	            return new ActionResult(false, message, toView(po));
490	        }
491	
492	        int unfinished = repo.countUnfinishedSteps(req.requestId());
493	        if (unfinished == 0) {
494	            String message = "恰在窗口终点全部步骤已完成，步骤有效，不判定超期";
495	            insertEvent(req.requestUid(), req.requestId(), EventType.EXPIRE_CHECK, null, fp,
496	                    message, false);
497	            return new ActionResult(false, message, toView(po));
498	        }
499	
500	        String m = "窗口结束时间 " + po.getWindowEnd() + " 仍有 " + unfinished
501	                + " 个未完成步骤，转 WINDOW_EXPIRED 并强制回退";
502	        triggerRollback(po, steps, "WINDOW_EXPIRED", null, req.atTime());
503	        insertEvent(req.requestUid(), req.requestId(), EventType.EXPIRE_CHECK, null, fp,
504	                m, false);
505	        return new ActionResult(false, m, toView(repo.lockRequest(req.requestId())));
506	    }
507	
508	    // ---------------- 封板 ----------------
509	
510	    @Transactional
511	    public ActionResult seal(SealRequest req) {
512	        String fp = FingerprintUtil.sha256("SEAL", req.requestId());
513	        CutoverEventPO existed = repo.findEvent(req.requestUid());
514	        if (existed != null) {
515	            return resolveIdempotent(existed, fp, req.requestId());
516	        }
517	
518	        CutoverRequestPO po = mustLock(req.requestId());
519	        CutoverEventPO afterLock = repo.findEvent(req.requestUid());
520	        if (afterLock != null) {
521	            return resolveIdempotent(afterLock, fp, req.requestId());
522	        }
523	        if (RequestStatus.SEALED.name().equals(po.getStatus())) {
524	            // 不同 requestUid 的重复封板同样幂等成功。
525	            insertEvent(req.requestUid(), req.requestId(), EventType.SEAL, null, fp,
526	                    "割接已封板，重复封板幂等成功", false);
527	            return new ActionResult(true, "割接已封板，重复封板幂等成功", toView(po));
528	        }
529	        if (RequestStatus.ROLLED_BACK.name().equals(po.getStatus())
530	                || RequestStatus.WINDOW_EXPIRED.name().equals(po.getStatus())) {
531	            throw new BusinessRuleException("割接已回退（" + po.getRollbackCause()
532	                    + "），终态唯一，不能封板");
533	        }
534	        if (!RequestStatus.VERIFIED.name().equals(po.getStatus())) {
535	            throw new BusinessRuleException("只有 VERIFIED 状态可以封板，当前状态 "
536	                    + po.getStatus());
537	        }
538	        po.setStatus(RequestStatus.SEALED.name());
539	        po.setUpdatedAt(LocalDateTime.now());
540	        repo.updateMutable(po);
541	        insertEvent(req.requestUid(), req.requestId(), EventType.SEAL, null, fp,
542	                "验证封板完成，状态 SEALED", false);
543	        return new ActionResult(false, "验证封板完成，状态 SEALED", toView(po));
544	    }
545	
546	    // ---------------- 查询 ----------------
547	
548	    @Transactional(readOnly = true)
549	    public RequestView get(String requestId) {
550	        CutoverRequestPO po = repo.findRequest(requestId);
551	        if (po == null) {
552	            throw new NotFoundException("割接申请不存在: " + requestId);
553	        }
554	        return toView(po);
555	    }
556	
557	    @Transactional(readOnly = true)
558	    public List<EventView> events(String requestId) {
559	        if (repo.findRequest(requestId) == null) {
560	            throw new NotFoundException("割接申请不存在: " + requestId);
561	        }
562	        return repo.listEvents(requestId).stream()
563	                .map(e -> new EventView(e.getRequestUid(), e.getRequestId(),
564	                        e.getEventType(), e.getSeqNo(),
565	                        Boolean.TRUE.equals(e.getLateFlag()), e.getCreatedAt()))
566	                .toList();
567	    }
568	
569	    // ---------------- 内部方法 ----------------
570	
571	    /**
572	     * 在同一事务内下达回退指令：冻结所有未完成步骤、追加系统回退步骤、置唯一回退终态、
573	     * 记录回退判据命中。调用方必须已持有申请行与步骤行锁。
574	     */
575	    private void triggerRollback(CutoverRequestPO po, List<CutoverStepPO> steps,
576	                                 String cause, Integer triggerSeq, LocalDateTime at) {
577	        repo.freezeUnfinishedSteps(po.getRequestId());
578	
579	        int maxSeq = steps.stream().mapToInt(CutoverStepPO::getSeqNo).max().orElse(0);
580	        LocalDateTime now = LocalDateTime.now();
581	        CutoverStepPO rollbackStep = new CutoverStepPO();
582	        rollbackStep.setRequestId(po.getRequestId());
583	        rollbackStep.setSeqNo(maxSeq + 1);
584	        rollbackStep.setStepName("系统自动回退（判据: " + cause + "）");
585	        rollbackStep.setStepType(StepType.ROLLBACK.name());
586	        rollbackStep.setStatus(StepStatus.SUCCESS.name());
587	        rollbackStep.setStartedAt(at);
588	        rollbackStep.setReportedAt(at);
589	        rollbackStep.setCreatedAt(now);
590	        rollbackStep.setUpdatedAt(now);
591	        repo.insertStep(rollbackStep);
592	
593	        po.setRollbackCause(cause);
594	        po.setStatus("WINDOW_EXPIRED".equals(cause)
595	                ? RequestStatus.WINDOW_EXPIRED.name() : RequestStatus.ROLLED_BACK.name());
596	        po.setUpdatedAt(now);
597	        repo.updateMutable(po);
598	
599	        // 回退判据命中记录（幂等，便于重入/复算）。
600	        String triggerUid = "SYS-ROLLBACK-" + po.getRequestId() + "-" + cause;
601	        if (repo.findEvent(triggerUid) == null) {
602	            insertEvent(triggerUid, po.getRequestId(), EventType.ROLLBACK_TRIGGER,
603	                    triggerSeq,
604	                    FingerprintUtil.sha256("ROLLBACK", po.getRequestId(), cause, triggerSeq),
605	                    "命中回退判据: " + cause, false);
606	        }
607	    }
608	
609	    private void persistStep(CutoverStepPO step) {
610	        repo.updateStepState(step.getRequestId(), step.getSeqNo(), step.getStatus(),
611	                step.getStartedAt(), step.getReportedAt());
612	    }
613	
614	    private CutoverRequestPO mustLock(String requestId) {
615	        CutoverRequestPO po = repo.lockRequest(requestId);
616	        if (po == null) {
617	            throw new NotFoundException("割接申请不存在: " + requestId);
618	        }
619	        return po;
620	    }
621	
622	    private void insertEvent(String uid, String requestId, EventType type, Integer seqNo,
623	                             String fingerprint, String message, boolean late) {
624	        CutoverEventPO po = new CutoverEventPO();
625	        po.setRequestUid(uid);
626	        po.setRequestId(requestId);
627	        po.setEventType(type.name());
628	        po.setSeqNo(seqNo);
629	        po.setPayloadFingerprint(fingerprint);
630	        po.setResultSnapshot(writeSnapshot(message));
631	        po.setLateFlag(late);
632	        po.setCreatedAt(LocalDateTime.now());
633	        try {
634	            repo.insertEvent(po);
635	        } catch (DuplicateKeyException dup) {
636	            // 并发下同 uid 首事件已提交：交由调用方外层按幂等/冲突处理。
637	            CutoverEventPO winner = repo.findEvent(uid);
638	            if (winner != null && !winner.getPayloadFingerprint().equals(fingerprint)) {
639	                throw new ConflictException("requestUid=" + uid
640	                        + " 已存在但业务参数不一致（同键异参）");
641	            }
642	        }
643	    }
644	
645	    private ActionResult resolveIdempotent(CutoverEventPO existed, String fp, String requestId) {
646	        if (!existed.getPayloadFingerprint().equals(fp)) {
647	            throw new ConflictException("requestUid=" + existed.getRequestUid()
648	                    + " 已存在但业务参数不一致（同键异参），拒绝产生新记录");
649	        }
650	        String message = readSnapshotMessage(existed.getResultSnapshot());
651	        CutoverRequestPO fresh = repo.lockRequest(requestId);
652	        return new ActionResult(true, "同键同参重放，返回首次结果：" + message,
653	                fresh == null ? null : toView(fresh));
654	    }
655	
656	    private CutoverRequestPO buildNewRequest(CreateCutoverRequest req, String fp,
657	                                             RequestStatus status, String rejectReason) {
658	        LocalDateTime now = LocalDateTime.now();
659	        CutoverRequestPO po = new CutoverRequestPO();
660	        po.setRequestId(req.requestId());
661	        po.setTitle(req.title());
662	        po.setDeviceCode(req.deviceCode());
663	        po.setPriority(req.priority().name());
664	        po.setWindowStart(req.windowStart());
665	        po.setWindowEnd(req.windowEnd());
666	        po.setStatus(status.name());
667	        po.setFingerprint(fp);
668	        po.setRejectReason(rejectReason);
669	        po.setCreatedAt(now);
670	        po.setUpdatedAt(now);
671	        return po;
672	    }
673	
674	    private String fingerprintRequest(CreateCutoverRequest req) {
675	        List<Object> parts = new ArrayList<>();
676	        parts.add("CREATE");
677	        parts.add(req.requestId());
678	        parts.add(req.title());
679	        parts.add(req.deviceCode());
680	        parts.add(req.priority());
681	        parts.add(req.windowStart());
682	        parts.add(req.windowEnd());
683	        for (StepDefinition s : req.steps()) {
684	            parts.add(s.name());
685	            parts.add(s.type());
686	        }
687	        return FingerprintUtil.sha256(parts.toArray());
688	    }
689	
690	    private RequestView toView(CutoverRequestPO po) {
691	        List<CutoverStepPO> steps = repo.listSteps(po.getRequestId());
692	        List<StepView> stepViews = steps.stream()
693	                .map(s -> new StepView(s.getSeqNo(), s.getStepName(), s.getStepType(),
694	                        s.getStatus(), s.getStartedAt(), s.getReportedAt()))
695	                .toList();
696	        List<String> impacts = po.getImpactSystems() == null
697	                ? List.of()
698	                : Arrays.stream(po.getImpactSystems().split(","))
699	                    .filter(s -> !s.isEmpty()).toList();
700	        return new RequestView(po.getRequestId(), po.getTitle(), po.getDeviceCode(),
701	                po.getPriority(), po.getWindowStart(), po.getWindowEnd(), po.getStatus(),
702	                po.getImpactSystems() == null ? null : impacts,
703	                po.getRejectReason(), po.getRollbackCause(), stepViews);
704	    }
705	
706	    private String writeSnapshot(String message) {
707	        try {
708	            return JSON.writeValueAsString(java.util.Map.of("message", message));
709	        } catch (Exception e) {
710	            return "{}";
711	        }
712	    }
713	
714	    private String readSnapshotMessage(String snapshot) {
715	        if (snapshot == null || snapshot.isBlank()) {
716	            return "";
717	        }
718	        try {
719	            return JSON.readValue(snapshot, new TypeReference<java.util.Map<String, String>>() {
720	            }).getOrDefault("message", "");
721	        } catch (Exception e) {
722	            return "";
723	        }
724	    }
725	}
