/**
 * 数据中心割接窗口与回退判据 REST 接口。
 */
@RestController
@RequestMapping("/api/cutovers")
public class CutoverController {

    private final CutoverService service;

    public CutoverController(CutoverService service) {
        this.service = service;
    }

