                assertThat(batchService.get("BAT-C2").members().get(0).memberStatus())
                        .isEqualTo("STARTED");
            } else {
                // 启动先提交：版本/状态已变化，发布整批拒绝(422)
                assertThat(publishOutcome).isInstanceOf(BusinessRuleException.class);
                assertThat(batchService.get("BAT-C2")).isNull();
            }
