        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    @DisplayName("前置失败与后继启动并发：后继要么等待要么被阻断，绝不放行；最终一致阻断")
    void predecessorFailVsSuccessorStartRace() throws Exception {
